public class LongMultiplierTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("multiply(\"123\", \"45\")", "5535", LongMultiplier.multiply("123", "45"));
            check("multiply(\"9\", \"9\")", "81", LongMultiplier.multiply("9", "9"));
            check("multiply(\"0\", \"9999\")", "0", LongMultiplier.multiply("0", "9999"));
            check("multiply(\"1\", \"1\")", "1", LongMultiplier.multiply("1", "1"));
            check("multiply(\"10\", \"10\")", "100", LongMultiplier.multiply("10", "10"));
            check("multiply(\"250\", \"4\")", "1000", LongMultiplier.multiply("250", "4"));
            check("leading zeros in the input are ignored", "120", LongMultiplier.multiply("0012", "10"));
            check("beyond the range of long", "999999999998000000000001",
                    LongMultiplier.multiply("999999999999", "999999999999"));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
